update t_product
set title = #{title},
    price = #{price},
    version = version + 1
where id = #{id}
  and version = #{version}

update t_product
set status = #{status},
    version = version + 1
where id = #{id}
  and version = #{version}

update t_product
set available_stock = #{availableStock},
    version = version + 1
where id = #{id}
  and version = #{version}

update t_product
set locked_stock = locked_stock - #{quantity},
    sold_stock = sold_stock + #{quantity},
    version = version + 1
where id = #{id}
  and locked_stock >= #{quantity}

update t_product
set available_stock = available_stock + #{quantity},
    locked_stock = locked_stock - #{quantity},
    version = version + 1
where id = #{id}
  and locked_stock >= #{quantity}

update t_product
set available_stock = available_stock + #{quantity},
    sold_stock = sold_stock - #{quantity},
    version = version + 1
where id = #{id}
  and sold_stock >= #{quantity}
